example.code:
using Devinno.Communication.LS.CNet;
using Devinno.Communication.LS.Data;   // LsValue, LsCommand

var cnet = new LsCNet { Port = "COM5", Baudrate = 9600 };
cnet.AutoRSB(1, 1, "%MW100", 10);
cnet.DataReceived += (s, e) => { if (e.MessageID == 1) Console.WriteLine(string.Join(",", e.Values)); };
cnet.DeviceOpened += (s, e) =>
{
    // 쓰기는 포트가 열린 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    cnet.ManualWSS(10, 1, [new LsValue("%MW200", 1234), new LsValue("%MW201", 5)]);
    cnet.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Slave="1" Device="%MW300" />를 이름으로 호출
};
cnet.Start();

using Devinno.Communication.LS.FEnet;
using Devinno.Communication.LS.Data;   // LsValue, LsCommand

var fenet = new LsFEnet { RemoteIP = "192.168.0.20" };
fenet.AutoRSB(1, "%MW100", 10);
fenet.DataReceived += (s, e) => { if (e.MessageID == 1) Console.WriteLine(string.Join(",", e.Values)); };
fenet.DeviceOpened += (s, e) =>
{
    // 쓰기는 연결된 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    fenet.ManualWSB(10, "%MW200", [1, 2, 3]);
    fenet.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Device="%MW300" />를 이름으로 호출
};
fenet.Start();

using Devinno.Communication.Mitsubishi.Ethernet;
using Devinno.Communication.Mitsubishi.Data;   // McCommand, McXYNotation

// Q/L/FX5 (3E)
var mc = new McEthernet { RemoteIP = "192.168.0.30", RemotePort = 5000, Frame = McFrame.E3 };
mc.AutoWR(1, "D100", 10);
mc.AutoBR(2, "M0", 32);
mc.DataReceived += (s, e) => Console.WriteLine($"{e.MessageID} {e.Device}: {string.Join(",", e.Values)}");
mc.NAKReceived += (s, e) => Console.WriteLine($"오류 {e.ErrorCode:X4}");
mc.DeviceOpened += (s, e) =>
{
    // 쓰기는 연결된 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    mc.ManualWW(10, "D200", [1234, -1]);
    mc.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Device="D200" />를 이름으로 호출
};
mc.Start();

// FX3U-ENET-ADP (1E, X/Y 8진수)
var fx = new McEthernet { RemoteIP = "192.168.0.31", RemotePort = 5002, Frame = McFrame.E1 };
fx.AutoBR(1, "X0", 16);
fx.Start();

using Devinno.Communication.Mitsubishi.Serial;
using Devinno.Communication.Mitsubishi.Data;   // McCommand, McXYNotation

var mc = new McSerial { Port = "COM3", Baudrate = 9600, Format = McSerialFormat.Format1, SumCheck = true };
mc.AutoWR(1, 0, "D100", 10);
mc.AutoBR(2, 0, "X0", 16);
mc.DataReceived += (s, e) => Console.WriteLine($"{e.MessageID} {e.Device}: {string.Join(",", e.Values)}");
mc.NAKReceived += (s, e) => Console.WriteLine($"NAK {e.ErrorCode:X2}");
mc.DeviceOpened += (s, e) =>
{
    // 쓰기는 포트가 열려 있는 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    mc.ManualWW(10, 0, "D200", [1234, -1]);
    mc.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Slave="0" Device="D200" />를 이름으로 호출
};
mc.Start();

var mb = new ModbusRTUMaster { Port = "COM3", Baudrate = 115200, AutoReconnect = true };
mb.AutoWordRead_FC3(1, 1, 0, 10);
mb.WordReadReceived += (s, e) => { if (e.MessageID == 1) Console.WriteLine(string.Join(",", e.ReceiveData)); };
mb.DeviceOpened += (s, e) =>
{
    // 쓰기는 포트가 열린 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    mb.ManualWordWrite_FC6(10, 1, 100, 1234);
    mb.NamedWrite("레시피", [1, 2, 3]);   // XML의 <Write Name="레시피" Id="30" Func="FC16" Slave="1" Start="10" />를 이름으로 호출
};
mb.Start();

var hold = new int[1000];
var slave = new ModbusRTUSlave { Port = "COM4", Baudrate = 115200, Slave = 1, HoldingRegisters = hold };
slave.WordWritten += (s, e) => Console.WriteLine($"{e.StartAddress}부터 {e.Length}개 변경");
slave.Start();
lock (slave.SyncRoot) { hold[0] = 1; hold[1] = 2; }

var mb = new ModbusTCPMaster { RemoteIP = "192.168.0.10", RemotePort = 502 };
mb.AutoWordRead_FC3(1, 1, 0, 10);
mb.WordReadReceived += (s, e) => { if (e.MessageID == 1) Console.WriteLine(string.Join(",", e.ReceiveData)); };
mb.DeviceOpened += (s, e) =>
{
    // 쓰기는 연결된 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    mb.ManualWordWrite_FC6(10, 1, 100, 1234);
    mb.NamedWrite("레시피", [1, 2, 3]);   // XML의 <Write Name="레시피" Id="30" Func="FC16" Slave="1" Start="10" />를 이름으로 호출
};
mb.Start();

var slave = new ModbusTCPSlave { LocalPort = 502, Slave = 1, HoldingRegisters = new int[1000] };
slave.ClientConnected += (s, e) => Console.WriteLine($"접속: {e.RemoteEndPoint}");
slave.Start();

using Devinno.Communication.Mqtt;

var mq = new MQClient { BrokerHostName = "192.168.0.10", BrokerPort = 1883 };
mq.Subscribe("sensor/#", MQQos.LeastOnce);
mq.Connected += (s, e) => Console.WriteLine("접속");
mq.Disconnected += (s, e) => Console.WriteLine("끊김");
mq.Received += (s, e) => Console.WriteLine($"{e.Topic}: {System.Text.Encoding.UTF8.GetString(e.Datas)}");
mq.Start("dev01", "user", "password");

mq.Publish("cmd/run", "1", MQQos.LeastOnce);
Console.WriteLine($"대기 {mq.PendingCount}건, 버림 {mq.DroppedCount}건");

mq.Dispose();

using Devinno.Communication.Omron.Data;      // FinsCommand
using Devinno.Communication.Omron.Ethernet;

var plc = new FinsTcp { RemoteIP = "192.168.250.1" };   // 노드 번호는 접속할 때 PLC가 정함
plc.AutoRead(1, ["D100", "W10.03"]);
plc.AutoReadBlock(2, "E0_0", 1000);
plc.DeviceOpened += (s, e) => Console.WriteLine($"접속: 클라이언트 노드 {plc.AssignedClientNode}, PLC 노드 {plc.ServerNode}");
plc.DataReceived += (s, e) => Console.WriteLine($"{e.MessageID}: {string.Join(",", e.Values)}");
plc.NAKReceived += (s, e) => Console.WriteLine($"종료 코드 0x{e.ErrorCode:X4}");
plc.DeviceOpened += (s, e) =>
{
    // 쓰기는 연결된 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    plc.ManualWrite(10, "H20.15", 1);
    plc.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Address="D200" />를 이름으로 호출
};
plc.Start();

using Devinno.Communication.Omron.Data;      // FinsCommand
using Devinno.Communication.Omron.Ethernet;

var plc = new FinsUdp { RemoteIP = "192.168.250.1" };   // DA1 = 1, SA1 = 이 PC IP 마지막 숫자
plc.AutoRead(1, ["D100", "CIO0.05", "W10"]);
plc.AutoReadBlock(2, "D1000", 800);   // 499워드 + 301워드로 나눠 읽음
plc.DataReceived += (s, e) =>
{
    if (e.MessageID == 1) Console.WriteLine($"D100 = {(short)e.Values[0]}, CIO0.05 = {e.Values[1]}");
    else Console.WriteLine($"{e.Addresses[0]}부터 {e.Values.Length}워드");
};
plc.NAKReceived += (s, e) => Console.WriteLine($"종료 코드 0x{e.ErrorCode:X4}");   // 예: 0x1103 주소 범위, 0x2102 쓰기 보호
plc.DeviceOpened += (s, e) =>
{
    // 쓰기는 소켓이 열려 있는 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    plc.ManualWrite(10, "D200", -1);
    plc.ManualWriteBlock(11, "CIO100.00", [1, 0, 1, 1]);   // 비트 4개
    plc.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Address="D200" />를 이름으로 호출
};
plc.Start();

using Devinno.Communication.Omron.Data;      // FinsCommand
using Devinno.Communication.Omron.Serial;

var plc = new FinsSerial { Port = "COM3", UnitNumber = 0 };   // 9600, 7, Even, 2 (Host Link 기본값)
plc.AutoRead(1, ["D100", "CIO0.00"]);
plc.AutoReadBlock(2, "D0", 100);
plc.DataReceived += (s, e) => Console.WriteLine($"{e.MessageID}: {string.Join(",", e.Values)}");
plc.FcsErrorReceived += (s, e) => Console.WriteLine("FCS 오류, 재시도");
plc.NAKReceived += (s, e) => Console.WriteLine($"종료 코드 0x{e.ErrorCode:X4}");
plc.DeviceOpened += (s, e) =>
{
    // 쓰기는 포트가 열려 있는 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    plc.ManualWrite(10, "D200", 1234);
    plc.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Address="D200" />를 이름으로 호출
};
plc.Start();

var s1f13 = new SecsMessage(1, 13, true, SecsItem.L());
var same = SecsMessage.ParseSml("S1F13 W <L>");
Console.WriteLine(s1f13.ToSml());   // S1F13 W <L [0]>

using Devinno.Communication.Secs.Data;
using Devinno.Communication.Secs.Gem;
using Devinno.Communication.Secs.Hsms;

var hsms = new SecsHsms { Mode = HsmsMode.Passive, LocalPort = 5000, DeviceID = 1 };
var eq = new GemEquipment(hsms) { ModelName = "DV-100", SoftwareRevision = "1.0.0" };
eq.AddStatusVariable(new GemStatusVariable(2001, "Temperature", SecsFormat.F4, "C"));
eq.AddDataVariable(new GemDataVariable(3001, "LotID", SecsFormat.ASCII));
eq.AddCollectionEvent(new GemCollectionEvent(5001, "ProcessStarted", [2001, 3001]));
eq.AddAlarm(new GemAlarm(1, "Over temperature", 2, 9001, 9002));
eq.AddRemoteCommand(new GemRemoteCommand("START", [new GemCommandParameter("LOTID", SecsFormat.ASCII)]));
eq.RemoteCommandReceived += (s, e) =>
{
    // 오래 걸리는 작업은 "받았고 나중에 끝냄"(4)으로 답하고 따로 실행, 끝나면 TriggerEvent로 알린다
    e.Hcack = GemAck.HcackAcceptedLater;
    var lot = e.Parameters.First(p => p.Name == "LOTID").Value.GetString();
    Task.Run(() => eq.TriggerEvent(5001, new Dictionary<GemId, SecsItem> { [3001] = SecsItem.A(lot) }));
};
eq.Start();

eq.SetValue(2001, SecsItem.F4(36.5f));   // 값 갱신
eq.SetAlarm(1);                           // 알람 발생 → S5F1 + CE 9001

using Devinno.Communication.Secs.Data;
using Devinno.Communication.Secs.Gem;
using Devinno.Communication.Secs.Hsms;

var hsms = new SecsHsms { Mode = HsmsMode.Active, RemoteIP = "192.168.0.50", RemotePort = 5000, DeviceID = 1 };
var host = new GemHost(hsms);
host.Subscribe(5001, 2001, 3001);                    // CE 5001이 일어나면 SV 2001, DV 3001 값을 받음
host.ConnectSequenceCompleted += (s, e) => Console.WriteLine(e.Success ? "준비됨" : $"접속 실패: {e.FailedStep} {e.Ack} {e.Exception?.Message}");
host.EventReceived += (s, e) => Console.WriteLine($"CE {e.Report.Ceid}: 온도 {e.Report.GetValue(2001)?.GetDouble()}");
host.AlarmReceived += (s, e) => Console.WriteLine($"알람 {e.Alid} {(e.IsSet ? "발생" : "해제")}: {e.Text}");
host.Start();                                        // 연결되면 S1F13 → S1F17 → 리포트 설정 → 알람 켜기

// 명령 (장비가 ON-LINE REMOTE일 때)
var result = await host.RemoteCommandAsync("START", [("LOTID", SecsItem.A("LOT-1"))]);
if (!result.IsAccepted) Console.WriteLine($"거절: HCACK {result.Hcack}");
byte eac = await host.WriteConstantsAsync([(4001, SecsItem.F4(120))]);

// 이벤트가 없는 현장: 앱 타이머로 SV를 주기적으로 읽기
using var timer = new PeriodicTimer(TimeSpan.FromSeconds(1));
while (await timer.WaitForNextTickAsync())
    if (host.IsCommunicating) Console.WriteLine((await host.ReadStatusAsync([2001]))[0].GetDouble());

using Devinno.Communication.Secs.Data;
using Devinno.Communication.Secs.Hsms;

// 호스트: 장비(Passive, 192.168.0.50:5000)에 접속
var host = new SecsHsms { Role = SecsRole.Host, Mode = HsmsMode.Active, RemoteIP = "192.168.0.50", RemotePort = 5000, DeviceID = 0 };
host.PrimaryReceived += (s, e) =>
{
    if (e.Message.Stream == 6 && e.Message.Function == 11)                 // 이벤트 보고
        e.Reply(new SecsMessage(6, 12, false, SecsItem.B(0)));
};
host.DeviceOpened += async (s, e) =>
{
    var reply = await host.SendAsync(new SecsMessage(1, 13, true, SecsItem.L()));   // 통신 수립
    Console.WriteLine(reply?.ToSml());
};
host.Start();

// 장비: 접속을 기다림
var eq = new SecsHsms { Role = SecsRole.Equipment, Mode = HsmsMode.Passive, LocalPort = 5000 };
eq.PrimaryReceived += (s, e) =>
{
    if (e.Message.Stream == 1 && e.Message.Function == 1)
        e.Reply(SecsMessage.ParseSml("S1F2 <L <A \"MDLN\"> <A \"1.0\">>"));
};
eq.Start();

using Devinno.Communication.Secs.Data;
using Devinno.Communication.Secs.Serial;

var eq = new SecsSerial { Role = SecsRole.Equipment, Port = "COM3", Baudrate = 9600, DeviceID = 1 };
eq.PrimaryReceived += (s, e) =>
{
    if (e.Message.Stream == 1 && e.Message.Function == 1)
        e.Reply(new SecsMessage(1, 2, false, SecsItem.L(SecsItem.A("MDLN"), SecsItem.A("1.0"))));
};
eq.Start();
var ack = eq.Send(new SecsMessage(5, 1, true, SecsItem.L(SecsItem.B(0x81), SecsItem.U4(1001), SecsItem.A("DOOR OPEN"))));

using Devinno.Communication.Siemens;

var plc = new S7Ethernet { RemoteIP = "192.168.0.10", Rack = 0, Slot = 1 };   // S7-1200/1500 (S7-300은 Slot = 2)
plc.AutoRead(1, ["DB1.DBW0", "DB1.DBD2", "M10.0"]);
plc.AutoReadBlock(2, "DB1.DBB100", 500);   // 500바이트, PDU 크기에 맞게 나눠 읽음
plc.DataReceived += (s, e) =>
{
    if (e.MessageID != 1) return;
    long word = e.Values[0];
    float real = BitConverter.Int32BitsToSingle((int)e.Values[1]);   // DB1.DBD2가 REAL인 경우
    bool flag = e.Values[2] == 1;
};
plc.BlockReceived += (s, e) => Console.WriteLine($"{e.Address}: {e.Data.Length}바이트");
plc.NAKReceived += (s, e) => Console.WriteLine($"오류 0x{e.ErrorCode:X2} (항목 {e.ItemIndex})");
plc.DeviceOpened += (s, e) =>
{
    // 쓰기는 연결된 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    plc.ManualWrite(10, [new S7Value("DB1.DBW0", 1234), new S7Value("M10.0", 1)]);
    plc.ManualWrite(11, [new S7Value("DB1.DBD4", BitConverter.SingleToInt32Bits(1.5f))]);   // REAL 쓰기
    plc.ManualWriteBlock(12, "DB2.DBB0", new byte[300]);
    plc.NamedWrite("속도", 1500);   // XML의 <Write Name="속도" Id="20" Address="DB1.DBW10" />를 이름으로 호출
};
plc.Start();

using Devinno.Communication.TextComm.RTU;

var tc = new TextCommRTUMaster { Port = "COM3", Baudrate = 115200 };
tc.AutoSend(1, 1, 0x41, "READ");
tc.MessageReceived += (s, e) => Console.WriteLine($"{e.MessageID} {e.Slave}/{e.Command}: {e.Message}");
tc.TimeoutReceived += (s, e) => Console.WriteLine($"응답 없음 {e.MessageID}");
tc.DeviceOpened += (s, e) =>
{
    // ManualSend는 포트가 열린 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    tc.ManualSend(10, 1, 0x42, "SET 100", repeatCount: 2);
};
tc.Start();

using Devinno.Communication.TextComm.RTU;

var slave = new TextCommRTUSlave { Port = "COM4", Baudrate = 115200 };
slave.MessageRequest += (s, e) =>
{
    if (e.Slave != 1) return;                         // 다른 국번: 응답 안 함 (ResponseMessage = null)
    if (e.Command == 0x41) e.ResponseMessage = "OK " + e.RequestMessage;
    else e.ResponseMessage = "";                       // 메시지 없이 응답
};
slave.Start();

using Devinno.Communication.TextComm.TCP;

var tc = new TextCommTCPMaster { RemoteIP = "192.168.0.50", RemotePort = 7897 };
tc.AutoSend(1, 1, 0x41, "READ");
tc.MessageReceived += (s, e) => Console.WriteLine($"{e.MessageID} {e.Slave}/{e.Command}: {e.Message}");
tc.CheckSumErrorReceived += (s, e) => Console.WriteLine($"합계 오류 {e.MessageID}");
tc.DeviceOpened += (s, e) =>
{
    // ManualSend는 연결된 동안에만 받습니다 (아니면 WriteDiscarded, NotConnected); 연결(재연결)될 때마다 다시 실행됩니다
    tc.ManualSend(10, 1, 0x42, "SET 100", repeatCount: 2);
};
tc.Start();

using Devinno.Communication.TextComm.TCP;

var slave = new TextCommTCPSlave { LocalPort = 7897, MaxClients = 4 };
slave.MessageRequest += (s, e) =>
{
    if (e.Command == 0x41) e.ResponseMessage = "OK " + e.RequestMessage;   // 그 밖의 명령은 응답 안 함
};
slave.ClientConnected += (s, e) => Console.WriteLine($"접속: {e.RemoteEndPoint}");
slave.Start();
